"use client";
import {
  useLayoutEffect,
  useRef,
  useState,
  type RefObject,
  type ReactNode,
  type HTMLAttributes,
} from "react";
import { createPositionMotion } from "./position-motion";
import "./selection-toolbar.css";
export interface SelectionAction {
  id: string;
  label: string;
  content: ReactNode;
}
export const textFormattingActions: SelectionAction[] = [
  { id: "bold", label: "Bold", content: <b>B</b> },
  { id: "italic", label: "Italic", content: <i>I</i> },
  { id: "underline", label: "Underline", content: <u>U</u> },
  { id: "strike", label: "Strikethrough", content: <s>S</s> },
  { id: "highlight", label: "Highlight", content: "▰" },
  { id: "inlineCode", label: "Inline code", content: "‹›" },
  { id: "codeBlock", label: "Code block", content: "{ }" },
  { id: "clear", label: "Clear styling", content: "T̸" },
];
export interface SelectionToolbarProps extends HTMLAttributes<HTMLDivElement> {
  editor: RefObject<HTMLElement | null>;
  onFormat: (command: string, range: Range) => void;
  actions?: SelectionAction[];
  getFormatState?: (command: string) => boolean;
  isActionDisabled?: (command: string) => boolean;
  active?: boolean;
}
/** The editor owns commands. This component only preserves a DOM selection and
 * renders contextual React controls; no document model or formatting engine. */
export function SelectionToolbar({
  editor,
  onFormat,
  actions = textFormattingActions,
  getFormatState,
  isActionDisabled,
  active = true,
  className = "",
  ...props
}: SelectionToolbarProps) {
  const root = useRef<HTMLDivElement>(null),
    saved = useRef<Range | null>(null);
  const [visible, setVisible] = useState(false),
    [, refresh] = useState(0);
  useLayoutEffect(() => {
    const node = editor.current;
    if (!node) return;
    const update = () => {
      if (!active) {
        setVisible(false);
        return;
      }
      const s = getSelection();
      if (root.current?.contains(document.activeElement)) return;
      const inside =
        !!s?.rangeCount &&
        !s.isCollapsed &&
        node.contains(s.anchorNode) &&
        node.contains(s.focusNode);
      if (inside) saved.current = s!.getRangeAt(0).cloneRange();
      setVisible(active && inside);
      refresh((n) => n + 1);
    };
    document.addEventListener("selectionchange", update);
    node.addEventListener("input", update);
    update();
    return () => {
      document.removeEventListener("selectionchange", update);
      node.removeEventListener("input", update);
    };
  }, [editor, active]);
  const motion = useRef<ReturnType<typeof createPositionMotion> | null>(null);
  useLayoutEffect(() => {
    const node = root.current!;
    motion.current = createPositionMotion(node, { x: 0, y: 1 }, (p) => {
      node.style.transform = `translateY(${p.y * 70}px)`;
      node.style.opacity = String(Math.max(0, Math.min(1, 1 - p.y)));
    });
    return () => {
      motion.current?.dispose();
    };
  }, []);
  useLayoutEffect(() => {
    const node = root.current!;
    if (visible && !node.matches(":popover-open")) node.showPopover();
    motion.current?.to(
      { x: 0, y: visible ? 0 : 1 },
      matchMedia("(prefers-reduced-motion: reduce)").matches,
      {
        spring: { stiffness: 100, mass: 1, damping: visible ? 20 : 16 },
        onFinish: () => {
          if (!visible && node.matches(":popover-open")) node.hidePopover();
        },
      },
    );
  }, [visible]);
  const apply = (command: string) => {
    const range = saved.current,
      node = editor.current;
    if (!range || !node?.contains(range.commonAncestorContainer)) return;
    node.focus({ preventScroll: true });
    const selection = getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
    onFormat(command, range.cloneRange());
    if (selection?.rangeCount)
      saved.current = selection.getRangeAt(0).cloneRange();
    refresh((n) => n + 1);
  };
  return (
    <div
      {...props}
      ref={root}
      popover="manual"
      role="toolbar"
      aria-label={props["aria-label"] ?? "Text formatting"}
      className={`roc-selection-toolbar ${className}`}
      inert={!visible}
      onKeyDown={(e) => {
        props.onKeyDown?.(e);
        if (e.key === "Escape") {
          e.stopPropagation();
          setVisible(false);
          editor.current?.focus({ preventScroll: true });
        }
      }}
    >
      {actions.map((action) => (
        <button
          type="button"
          key={action.id}
          data-command={action.id}
          aria-label={action.label}
          title={action.label}
          aria-pressed={getFormatState?.(action.id) ?? false}
          disabled={isActionDisabled?.(action.id)}
          onPointerDown={(e) => e.preventDefault()}
          onClick={() => apply(action.id)}
        >
          {action.content}
        </button>
      ))}
    </div>
  );
}

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
import {
  DEFAULT_SPRING,
  sampleSpring,
  type SpringOptions,
} from "./physical-spring";
type Pose = { x: number; y: number; scale: number; rotation: number };
const poseOf = (p: { x: number; y: number }): Pose => ({
  ...p,
  scale: 1,
  rotation: 0,
});
type Point = { x: number; y: number };
export interface MotionOptions {
  spring?: SpringOptions;
  preserveVelocity?: boolean;
  progressVelocity?: number;
  onFinish?: () => void;
}
export interface GeometryPose extends Pose {
  width: number;
  height: number;
}
const keys = ["x", "y", "scale", "rotation", "width", "height"] as const;
/** One transform writer per retained shell. Optional painter also drives camera/lid. */
export function createPositionMotion(
  node: HTMLElement,
  initial: Point & Partial<GeometryPose>,
  painter?: (pose: GeometryPose) => void,
) {
  let position: GeometryPose = {
      ...poseOf(initial),
      width: 0,
      height: 0,
      ...initial,
    },
    velocity: GeometryPose = {
      x: 0,
      y: 0,
      scale: 0,
      rotation: 0,
      width: 0,
      height: 0,
    };
  let target = { ...position },
    from = { ...position },
    speed = { ...velocity },
    start = 0;
  let spring = DEFAULT_SPRING,
    frame = 0,
    safety: ReturnType<typeof setTimeout> | undefined,
    done: (() => void) | undefined,
    disposed = false;
  const paint = () =>
    painter
      ? painter(position)
      : (node.style.transform = `translate3d(${position.x}px, ${position.y}px, 0) rotate(${position.rotation}deg) scale(${position.scale})`);
  const sample = () => {
    const elapsed = (performance.now() - start) / 1000;
    for (const key of keys) {
      const value = sampleSpring(
        from[key],
        target[key],
        speed[key],
        elapsed,
        spring,
      );
      position[key] = value.position;
      velocity[key] = value.velocity;
    }
  };
  // Interrupt from the last painted frame, rather than advancing unseen geometry
  // to the event timestamp. Position and velocity already share that frame.
  const stop = () => {
    if (frame) {
      cancelAnimationFrame(frame);
      frame = 0;
    }
    clearTimeout(safety);
    done = undefined;
  };
  const finish = () => {
    cancelAnimationFrame(frame);
    frame = 0;
    clearTimeout(safety);
    position = { ...target };
    velocity = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
    paint();
    const callback = done;
    done = undefined;
    callback?.();
  };
  const tick = () => {
    if (disposed) return;
    sample();
    paint();
    if (
      performance.now() - start > 4000 ||
      keys.every(
        (key) =>
          Math.abs(position[key] - target[key]) <
            (key === "scale" ? 0.0001 : 0.02) &&
          Math.abs(velocity[key]) < (key === "scale" ? 0.001 : 0.1),
      )
    )
      finish();
    else frame = requestAnimationFrame(tick);
  };
  paint();
  return {
    read() {
      stop();
      return { ...position };
    },
    peek() {
      return { ...position };
    },
    set(point: Point & Partial<GeometryPose>) {
      stop();
      position = {
        ...poseOf(point),
        width: position.width,
        height: position.height,
        ...point,
      };
      target = { ...position };
      velocity = { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 };
      paint();
    },
    to(
      point: Point & Partial<GeometryPose>,
      reduced: boolean,
      options: MotionOptions = {},
    ) {
      if (disposed) return;
      stop();
      target = {
        ...poseOf(point),
        width: position.width,
        height: position.height,
        ...point,
      };
      done = options.onFinish;
      if (
        reduced ||
        keys.every(
          (key) => position[key] === target[key] && velocity[key] === 0,
        )
      ) {
        finish();
        return;
      }
      from = { ...position };
      speed =
        options.preserveVelocity === false
          ? { x: 0, y: 0, scale: 0, rotation: 0, width: 0, height: 0 }
          : { ...velocity };
      if (options.progressVelocity !== undefined)
        for (const key of keys)
          speed[key] = (target[key] - from[key]) * options.progressVelocity;
      spring = options.spring ?? DEFAULT_SPRING;
      start = performance.now();
      frame = requestAnimationFrame(tick);
      safety = setTimeout(finish, 4200);
    },
    finish,
    dispose() {
      disposed = true;
      stop();
    },
  };
}
export type PositionMotion = ReturnType<typeof createPositionMotion>;

// Extracted from Franklin Board React worktree; MIT. See SOURCE-LICENSE.txt.
export interface SpringOptions {
  stiffness: number;
  damping: number;
  mass: number;
}
export const DEFAULT_SPRING: SpringOptions = {
  stiffness: 400,
  damping: 38,
  mass: 1,
};
// Typed port of the retained legacy analytic spring; legacy source stays unchanged.
export function sampleSpring(
  from: number,
  to: number,
  velocity: number,
  seconds: number,
  options: Partial<SpringOptions> = {},
) {
  const {
    stiffness: k,
    damping: c,
    mass: m,
  } = { ...DEFAULT_SPRING, ...options };
  if (!(k > 0 && m > 0 && c >= 0))
    throw new RangeError("Invalid spring parameters");
  const t = Math.max(0, seconds),
    a = c / (2 * m),
    w2 = k / m,
    d = from - to;
  let x, v;
  if (Math.abs(a * a - w2) < 1e-7) {
    const b = velocity + a * d,
      e = Math.exp(-a * t);
    x = (d + b * t) * e;
    v = (b - a * (d + b * t)) * e;
  } else if (a * a < w2) {
    const w = Math.sqrt(w2 - a * a),
      b = (velocity + a * d) / w;
    const e = Math.exp(-a * t),
      cos = Math.cos(w * t),
      sin = Math.sin(w * t);
    x = e * (d * cos + b * sin);
    v = e * ((b * w - a * d) * cos - (d * w + a * b) * sin);
  } else {
    const q = Math.sqrt(a * a - w2),
      r1 = -a + q,
      r2 = -a - q;
    const b1 = (velocity - r2 * d) / (r1 - r2),
      b2 = d - b1;
    x = b1 * Math.exp(r1 * t) + b2 * Math.exp(r2 * t);
    v = r1 * b1 * Math.exp(r1 * t) + r2 * b2 * Math.exp(r2 * t);
  }
  return { position: to + x, velocity: v };
}

export type ContainerMotion =
  | "unfold"
  | "refold"
  | "pullReturn"
  | "dropGather"
  | "dropSink"
  | "lidOpen"
  | "lidClose";
/** Same parameter families as legacy src/spring.js; deterministic midpoint by default. */
export function containerSpring(
  kind: ContainerMotion,
  random = () => 0.5,
): SpringOptions {
  if (kind === "dropGather" || kind === "dropSink") {
    const mass =
      (kind === "dropGather"
        ? 0.24 + 0.08 * random()
        : 0.16 + 0.16 * random()) * 0.48;
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "unfold")
    return { stiffness: 240, damping: 20, mass: 0.8 + 0.16 * random() };
  if (kind === "refold") {
    const mass = 0.12 + 0.12 * random();
    return { stiffness: 100, damping: 2 * Math.sqrt(100 * mass), mass };
  }
  if (kind === "pullReturn")
    return { stiffness: 400, damping: 24, mass: (0.8 + 0.4 * random()) * 0.64 };
  if (kind === "lidOpen") return { stiffness: 100, damping: 10, mass: 0.64 };
  return { stiffness: 100, damping: 2 * Math.sqrt(100 * 0.32), mass: 0.32 };
}

/** Legacy document/image presentation profile: critically damped, softer opening. */
export function presentationSpring(opening: boolean): SpringOptions {
  const mass = opening ? 0.48 : 0.32;
  return { stiffness: 100, mass, damping: 2 * Math.sqrt(100 * mass) };
}

@import "./surface.css";
.roc-selection-toolbar {
  position: fixed;
  inset: auto 10px 24px;
  margin: 0 auto;
  width: max-content;
  max-width: calc(100vw - 20px);
  border: 1px solid #ffffff24;
  padding: 6px;
  border-radius: var(--roc-radius, 14px);
  background: var(--roc-toolbar, #292b28);
  color: var(--roc-toolbar-ink, #fff);
  box-shadow: 0 8px 30px #0002;
  overflow-x: auto;
  gap: 3px;
  opacity: 0;
}
.roc-selection-toolbar:popover-open {
  display: flex;
}
.roc-selection-toolbar button {
  border: 0;
  background: none;
  color: inherit;
  border-radius: var(--roc-radius, 8px);
  min-width: 32px;
  min-height: 32px;
  font-size: 13px;
}
.roc-selection-toolbar button[aria-pressed="true"] {
  background: #ffffff30;
}
.roc-selection-toolbar button:disabled {
  opacity: 0.35;
}

/* Shared surface primitives only. Tokens inherit from the host. No page reset. */
:where(
  .roc-expand,
  .roc-folder,
  .roc-sources,
  .roc-lanes,
  .roc-tabs,
  .roc-card-preview,
  .roc-image-viewport,
  .roc-voice,
  .roc-selection-toolbar,
  .roc-page-book,
  .roc-source-tray
) {
  color: var(--roc-ink, #30332e);
  font-family: inherit;
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  * {
  box-sizing: border-box;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
:where(
    .roc-expand,
    .roc-folder,
    .roc-sources,
    .roc-lanes,
    .roc-tabs,
    .roc-card-preview,
    .roc-image-viewport,
    .roc-voice,
    .roc-selection-toolbar,
    .roc-page-book,
    .roc-source-tray
  )
  button:focus-visible {
  outline: 2px solid var(--roc-accent, #64735f);
  outline-offset: 3px;
}
.roc-eyebrow {
  font:
    10px/1.4 ui-monospace,
    monospace;
  letter-spacing: 0.12em;
  color: var(--roc-muted, #757b72);
}
.roc-text-button {
  border: 0;
  background: none;
  padding: 9px 0;
  font-size: 12px;
  text-align: left;
  display: inline-flex;
  gap: 20px;
  align-items: center;
}
